// A miniature painted nightscape, composed in depth at a fixed pixel resolution.
const bossProfiles=[
 {name:'Vex, karetní mág',mode:'Karetní souboj',rune:'♧',loot:'Pečeť arkány',color:'#cb9cff',sky:'#211430',light:'#976baf',desc:'Prohlédni zrcadlení a zahraj správnou kartu.'},
 {name:'Nyx, drak ozvěn',mode:'Úder ozvěny',rune:'✧',loot:'Krystal ozvěny',color:'#83f4e5',sky:'#0b2434',light:'#40848d',desc:'Vzpomeň si na odpověď dřív, než se drak rozletí.'},
 {name:'Ignis, sluneční fénix',mode:'Karetní souboj',rune:'☼',loot:'Pero úsvitu',color:'#ffb868',sky:'#321724',light:'#c47955',desc:'Prolom sluneční clonu salvou a vyhni se ohnivé smršti.'},
 {name:'Aster, strážce polární záře',mode:'Úder ozvěny',rune:'❄',loot:'Hvězdný paroh',color:'#a6cbff',sky:'#14233a',light:'#627eaa',desc:'Odpovídej zpaměti a udeř, když parohy sbírají náboj.'}
];
const realm=new Image();realm.src='data:image/webp;base64,';
const spirits=["data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,"].map(src=>{let img=new Image();img.src=src;return img});
const smooth=v=>{v=Math.max(0,Math.min(1,v));return v*v*(3-2*v)};
function artwork(c,img,x,y,sz,lean=0){if(!img.complete||!img.naturalWidth)return;c.save();c.translate(x,y);c.rotate(lean);let f=sz/Math.max(img.naturalWidth,img.naturalHeight);c.drawImage(img,-img.naturalWidth*f/2,-img.naturalHeight*f,img.naturalWidth*f,img.naturalHeight*f);c.restore()}
function drawPortrait(canvas,id){
 const hero=id===-1,p=bossProfiles[hero?0:id];let img=spirits[hero?5:id+1];
 function render(){let w=1000,h=hero?440:400;canvas.width=w;canvas.height=h;let c=canvas.getContext('2d');let sky=c.createRadialGradient(w*.52,h*.35,5,w*.5,h*.4,w*.63);sky.addColorStop(0,p.light);sky.addColorStop(.55,p.sky);sky.addColorStop(1,'#0a0d18');c.fillStyle=sky;c.fillRect(0,0,w,h);
 if(realm.complete&&realm.naturalWidth){c.globalAlpha=hero?.95:.4;c.drawImage(realm,0,-h*.18,w,h*1.4);c.globalAlpha=1}for(let j=0;j<85;j++){let x=(j*613)%w,y=(j*j*19)%h;c.fillStyle=j%4?'#ffffff50':p.color;c.beginPath();c.arc(x,y,.6+j%3,0,7);c.fill()}
 for(let k=0;k<3;k++){c.strokeStyle=p.color+'4c';c.lineWidth=k?1:2;c.beginPath();c.ellipse(w*.5,h*.6,160+k*23,160+k*23,0,0,7);c.stroke()}
 artwork(c,img,w*(hero?.57:.51),h*(hero?1.02:1.07),hero?470:435)}
 if(img.complete)render();else img.addEventListener('load',render,{once:true});if(!realm.complete)realm.addEventListener('load',render,{once:true})
}
function lightning(c,x0,y0,x1,y1,seed,col,width){
 const pts=[],dx=x1-x0,dy=y1-y0,len=Math.hypot(dx,dy)||1;
 for(let j=0;j<=17;j++){let t=j/17,noise=Math.sin(j*91.7+seed)*Math.cos(j*5.17+seed*.31)*Math.sin(Math.PI*t)*Math.min(24,len*.16);pts.push([x0+dx*t-dy/len*noise,y0+dy*t+dx/len*noise])}
 const stroke=(arr,color,size)=>{c.beginPath();arr.forEach(([x,y],j)=>j?c.lineTo(x,y):c.moveTo(x,y));c.strokeStyle=color;c.lineWidth=size;c.stroke()};
 c.save();c.lineCap='round';c.lineJoin='round';c.shadowColor=col;c.shadowBlur=14;stroke(pts,col,width*2.5);stroke(pts,'#f7fbff',width*.65);for(let j=4;j<15;j+=4){let [x,y]=pts[j];stroke([[x,y],[x+11,y-8],[x+6,y-18],[x+24,y-31]],col,width*.55)}c.restore()
}

function duelStage(scene,boss){
 const canvas=document.createElement('canvas');canvas.className='duelLayer';scene.append(canvas);
 const c=canvas.getContext('2d'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 let motion=null,running=true,raf;
 const path=(points,fill,stroke,width=2)=>{c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));if(fill){c.closePath();c.fillStyle=fill;c.fill()}if(stroke){c.strokeStyle=stroke;c.lineWidth=width;c.stroke()}};
 const ellipse=(x,y,rx,ry,color)=>{c.fillStyle=color;c.beginPath();c.ellipse(x,y,rx,ry,0,0,7);c.fill()};
 function ring(x,y,r,color,width){c.strokeStyle=color;c.lineWidth=width;c.beginPath();c.arc(x,y,r,0,7);c.stroke()}
 function frame(now){if(!running||!scene.isConnected)return;const w=scene.clientWidth,h=scene.clientHeight,d=Math.min(devicePixelRatio||1,2);if(!w||!h){raf=requestAnimationFrame(frame);return}if(canvas.width!==Math.round(w*d)||canvas.height!==Math.round(h*d)){canvas.width=Math.round(w*d);canvas.height=Math.round(h*d)}
 const scale=Math.min(w/810,h/315);c.setTransform(d,0,0,d,0,0);let backdrop=c.createLinearGradient(0,0,0,h);backdrop.addColorStop(0,boss?"#0a2034":"#1b1639");backdrop.addColorStop(1,"#202331");c.fillStyle=backdrop;c.fillRect(0,0,w,h);if(realm.complete&&realm.naturalWidth){c.save();c.globalAlpha=.36;let f=Math.max(w/realm.width,h/realm.height);c.drawImage(realm,(w-realm.width*f)/2,(h-realm.height*f)/2,realm.width*f,realm.height*f);c.restore()}c.setTransform(scale*d,0,0,scale*d,(w-900*scale)*d/2,(h-330*scale)*d*.50);let t=reduced?0:now/1000,m=motion,u=m?Math.min(1,(now-m.start)/m.time):1,enemy=m?.kind==='enemy',attack=m&&u<1,impact=attack?Math.max(0,1-Math.abs(u-.64)*8):0;
 let sky=c.createLinearGradient(0,0,0,330);sky.addColorStop(0,bossProfiles[boss].sky);sky.addColorStop(.72,bossProfiles[boss].light);sky.addColorStop(1,'#151e2b');
 c.save();
 const p=bossProfiles[boss],castX=enemy?650:224,hitX=enemy?224:650;
 if(attack&&!reduced){
   const focus=smooth(u/.17)*(1-smooth((u-.79)/.21)),flight=smooth((u-.27)/.36);
   const zoom=1+focus*(1.12+.24*(1-flight)),cx=450+(castX+(hitX-castX)*flight-450)*focus,cy=165+(154-165)*focus;
   c.translate(450,165);c.scale(zoom,zoom);c.translate(-cx,-cy)
 }
 if(!reduced)c.translate(Math.sin(u*95)*impact*5,0);
 if(realm.complete&&realm.naturalWidth){
 c.drawImage(realm,-160,-276,1220,688);c.fillStyle=p.sky+'30';c.fillRect(-160,-276,1220,688);
 }
 for(let j=0;j<40;j++){let x=(j*137+t*8)%910,y=196-((j*29+t*(4+j%4))%154);ellipse(x,y,1.4,1.4,boss?'#9ce9cc':'#d8addf')}
 let dash=attack&&m.kind==='blade'?Math.sin(Math.PI*Math.min(1,u/.84))**2*358:0;let strike=attack&&!enemy?Math.sin(u*Math.PI):0;
 ellipse(224,229,41,6,'#161a26');ellipse(660,225,67,7,'#171a26');
 const idle=Math.sin(t*2),power=attack?Math.sin(Math.PI*Math.min(1,u/.3)):0;
 artwork(c,spirits[0],224+dash-(enemy?impact*22:0),227+idle,128+4*strike,enemy?impact*.13:-power*.08);
 artwork(c,spirits[boss+1],657+(!enemy?impact*28:0)-(enemy&&attack?Math.sin(u*Math.PI)*37:0),224+idle*(boss===2?8:2),boss===0?153:175,(!enemy?impact*.12:power*-.11));
 if(attack){let col=m.color,x0=enemy?603:255,x1=enemy?224:638,k=Math.max(0,Math.min(1,(u-.21)/.42)),x=x0+(x1-x0)*k;
 c.shadowBlur=15;c.shadowColor=col;
 if(m.kind==='ward'){for(let j=0;j<3;j++){c.save();c.translate(224,173);c.rotate(u*3+j*1.047);c.strokeStyle=col;c.lineWidth=2;c.beginPath();c.ellipse(0,0,53,20,0,0,7);c.stroke();c.restore()}ring(224,173,48+8*Math.sin(u*3),col,2)}
 else if(u<.22){for(let j=0;j<14;j++){let angle=j*.449+u*7,r=(1-u/.22)*39+5;ellipse(x0+Math.cos(angle)*r,158+Math.sin(angle)*r,1.8,1.8,col)}ring(x0,158,10+u*92,col,2)}
 else if(u<.68){if(m.kind==='blade'){for(let j=0;j<5;j++){c.globalAlpha=1-j*.17;c.strokeStyle=j?'#c2eaff':col;c.lineWidth=8-j;c.beginPath();c.ellipse(250+dash-j*4,150,59+j*2,37+j*2,-.55,-2.4+u*2,.3+u*2);c.stroke()}c.globalAlpha=1}
 else if(m.kind==='storm'||(enemy&&boss===3)){lightning(c,x0,158,x,158,Math.floor(u*40),col,2.6);lightning(c,x-35,32,x,161,Math.floor(u*36)+9,col,1.6)}
 else if(enemy&&boss===2){for(let j=0;j<26;j++){let v=j/26;let yy=157+Math.sin(v*7+u*11)*13*v;ellipse(x0+(x-x0)*v,yy,8+v*9,4+v*7,j%3?'#ff8e39':'#fff19b')}}
 else if(m.kind==='beam'||(enemy&&boss)){path([[x0,158],[x,151-8*k],[x,168+6*k]],col);path([[x0,158],[x,159]],null,'#fff',3)}
 else if(m.kind==='mark'){ring(x,160,14,col,3);path([[x,137],[x+10,160],[x,183],[x-10,160],[x,137]],null,col,2)}
 else for(let j=0;j<(m.kind==='volley'||enemy?3:1);j++){let yy=158+(j-1)*18*Math.sin(k*Math.PI);if(enemy){c.save();c.translate(x-j*8,yy);c.rotate(k*8+j);c.fillStyle=col;c.fillRect(-6,-10,12,20);c.restore()}else{path([[x-38,yy+3],[x,yy]],null,col,4);ellipse(x,yy,m.kind==='nova'?18:5,m.kind==='nova'?18:5,col)}}}
 if(u>.58&&u<.76&&m.kind!=='ward'){let g=c.createRadialGradient(x1,161,0,x1,161,65);g.addColorStop(0,'#fffbea');g.addColorStop(.18,col);g.addColorStop(1,col+'00');c.globalAlpha=.75*(1-(u-.58)/.18);c.fillStyle=g;c.fillRect(x1-65,96,130,130);c.globalAlpha=1}
 if(u>.58&&m.kind!=='ward'){let z=(u-.58)/.42;c.globalAlpha=1-z;ring(x1,161,4+z*53,col,3);for(let i=0;i<28;i++){let a=i*2.4,r=z*(34+i%7*9);path([[x1+Math.cos(a)*r,161+Math.sin(a)*r],[x1+Math.cos(a)*(r+6),161+Math.sin(a)*(r+6)]],null,col,2)}}
 }
 c.restore();raf=requestAnimationFrame(frame)}
 frame(performance.now());return{play(kind,color){const time=reduced?150:(kind==="storm"||kind==="beam"?1660:1290);motion={kind,color,time,start:performance.now()};return new Promise(r=>setTimeout(r,time))},stop(){running=false;cancelAnimationFrame(raf)}}
}
